export type LaneName = (typeof closedSetLanes)[number];
export type RunStateName = (typeof closedSetRunStates)[number];
export type AttentionKind = (typeof closedSetAttentionKinds)[number];
export type TargetColumn = (typeof closedSetTargetColumns)[number];
export type ThemeToken = (typeof closedSetThemeTokens)[number];
export type LaunchState = (typeof closedSetLaunchStates)[number];

